package com.foodflow.orders.config;
import feign.RequestInterceptor;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.web.context.request.RequestContextHolder;import org.springframework.web.context.request.ServletRequestAttributes;
@Configuration public class FeignConfig { @Bean RequestInterceptor authForwardingInterceptor() { return template -> { var attrs=(ServletRequestAttributes)RequestContextHolder.getRequestAttributes(); if(attrs!=null){String auth=attrs.getRequest().getHeader("Authorization");String user=attrs.getRequest().getHeader("X-Auth-User-Id");String role=attrs.getRequest().getHeader("X-Auth-User-Role");if(auth!=null)template.header("Authorization",auth);if(user!=null)template.header("X-Auth-User-Id",user);if(role!=null)template.header("X-Auth-User-Role",role);} }; } }
